SELECT DISTINCT dataset.sig, m0.output as m, n0.output as n, D0.output as D(n,m), e_nm0.output as e_nm(n,m,D(n,m)), iso0.output as iso(G,e_nm(n,m,D(n,m))) FROM ((SELECT * FROM ((SELECT sig, all_expr.expr0 as eci, all_expr.expr1 as n, all_expr.expr2 as m FROM ((SELECT dataset.sig, eci0.output as expr0, n0.output as expr1, m0.output as expr2 FROM ((SELECT DISTINCT dataset.sig, m0.output as m, n0.output as n, D0.output as D(n,m) FROM ((SELECT DISTINCT dataset.sig, is_connected0.output as is_connected, m0.output as m, n0.output as n FROM ((SELECT * FROM (dataset))) as dataset JOIN (is_connected) as is_connected0  ON is_connected0.graph = dataset.sig JOIN (m) as m0  ON m0.graph = dataset.sig JOIN (n) as n0  ON n0.sig = dataset.sig  WHERE ((n0.output) - (1) <= m0.output) AND ((m0.output <= ((n0.output) * ((n0.output) - (1))) / (2)) AND (is_connected0.output = 1)))) as dataset JOIN (m) as m0  ON m0.graph = dataset.sig JOIN (n) as n0  ON n0.sig = dataset.sig JOIN (D) as D0  ON D0.n = n0.output AND D0.m = m0.output  WHERE D0.output >= 3)) as dataset JOIN (eci) as eci0  ON eci0.graph = dataset.sig JOIN (m) as m0  ON m0.graph = dataset.sig JOIN (n) as n0  ON n0.sig = dataset.sig )) as all_expr JOIN ((SELECT MAX(expr0) as expr0, expr1, expr2 FROM ((SELECT dataset.sig, eci0.output as expr0, n0.output as expr1, m0.output as expr2 FROM ((SELECT DISTINCT dataset.sig, m0.output as m, n0.output as n, D0.output as D(n,m) FROM ((SELECT DISTINCT dataset.sig, is_connected0.output as is_connected, m0.output as m, n0.output as n FROM ((SELECT * FROM (dataset))) as dataset JOIN (is_connected) as is_connected0  ON is_connected0.graph = dataset.sig JOIN (m) as m0  ON m0.graph = dataset.sig JOIN (n) as n0  ON n0.sig = dataset.sig  WHERE ((n0.output) - (1) <= m0.output) AND ((m0.output <= ((n0.output) * ((n0.output) - (1))) / (2)) AND (is_connected0.output = 1)))) as dataset JOIN (m) as m0  ON m0.graph = dataset.sig JOIN (n) as n0  ON n0.sig = dataset.sig JOIN (D) as D0  ON D0.n = n0.output AND D0.m = m0.output  WHERE D0.output >= 3)) as dataset JOIN (eci) as eci0  ON eci0.graph = dataset.sig JOIN (m) as m0  ON m0.graph = dataset.sig JOIN (n) as n0  ON n0.sig = dataset.sig )) GROUP BY expr1, expr2)) as extr  ON all_expr.expr0 = extr.expr0 AND all_expr.expr1 = extr.expr1 AND all_expr.expr2 = extr.expr2 )) as dataset)) as dataset JOIN (m) as m0  ON m0.graph = dataset.sig JOIN (n) as n0  ON n0.sig = dataset.sig JOIN (D) as D0  ON D0.n = n0.output AND D0.m = m0.output JOIN (e_nm) as e_nm0  ON e_nm0.n = n0.output AND e_nm0.m = m0.output AND e_nm0.d_nm = D0.output JOIN (iso) as iso0  ON iso0.g1 = dataset.sig AND iso0.g2 = e_nm0.output  WHERE NOT (iso0.output = 1)\n;